def f(x, *a):
    return x + len(a)
print(f(10, 1, 2))

def f(*a, **k):
    return len(a) + len(k)
print(f(1, 2, b=3))

def f(a, b=2):
    return a + b
print(f(1), f(1, 5))

def f(a, b=2, c=3):
    return a + b + c
print(f(1, c=9))

def f(*a):
    s = 0
    for v in a:
        s += v
    return s
print(f(1, 2, 3, 4))

def f(**k):
    s = 0
    for key in k:
        s += k[key]
    return s
print(f(a=1, b=2))
